(function(){
'use strict';
const KEY='central-v6:pt:m4:v1';
let state={};
try{state=JSON.parse(localStorage.getItem(KEY)||'{}')}catch(e){state={}}
state.read=state.read||{};state.space=state.space||{};state.rounds=state.rounds||{};state.review=state.review||{};state.errors=Array.isArray(state.errors)?state.errors:[];
function save(){localStorage.setItem(KEY,JSON.stringify(state));update()}
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderTheory(){const host=document.getElementById('m4Theory');if(!host||!Array.isArray(window.PT_M4_SESSIONS))return;host.innerHTML=window.PT_M4_SESSIONS.map((s,i)=>'<details class="session" '+(i===0?'open':'')+'><summary>'+(i+1)+'. '+esc(s.title)+'</summary><div class="body">'+s.html+'<label class="check"><input type="checkbox" data-read="'+esc(s.id)+'"> Li e entendi esta sessão.</label></div></details>').join('');host.querySelectorAll('[data-read]').forEach(b=>b.onchange=()=>{state.read[b.dataset.read]=b.checked;save()})}
function renderPanels(){document.getElementById('m4Review').innerHTML='<label>Confiança <select id="m4Confidence"><option value="">Não avaliado</option><option>Baixa</option><option>Média</option><option>Alta</option></select></label> <label>Pontos frágeis <input id="m4Weak"></label> <button id="m4SaveReview">Salvar</button>';document.getElementById('m4Rounds').innerHTML='<label>R1/20 <input id="m4r1" type="number" min="0" max="20"></label> <label>R2/25 <input id="m4r2" type="number" min="0" max="25"></label> <label>Final/30 <input id="m4rf" type="number" min="0" max="30"></label> <button id="m4SaveRounds">Salvar</button> <span id="m4RoundPct"></span>';document.getElementById('m4Spaced').innerHTML=['24h','7d','30d'].map(v=>'<label class="check"><input type="checkbox" data-space="'+v+'"> Revisão '+v+'</label>').join('');document.getElementById('m4Errors').innerHTML='<input id="m4ErrTopic" placeholder="Tópico"><textarea id="m4ErrText" placeholder="Erro e correção"></textarea><button id="m4AddErr">Adicionar</button><div id="m4ErrList"></div>';document.getElementById('m4SaveReview').onclick=()=>{state.review={confidence:document.getElementById('m4Confidence').value,weak:document.getElementById('m4Weak').value};save()};document.getElementById('m4SaveRounds').onclick=()=>{state.rounds={r1:+document.getElementById('m4r1').value||0,r2:+document.getElementById('m4r2').value||0,rf:+document.getElementById('m4rf').value||0};save()};document.querySelectorAll('[data-space]').forEach(b=>b.onchange=()=>{state.space[b.dataset.space]=b.checked;save()});document.getElementById('m4AddErr').onclick=()=>{const t=document.getElementById('m4ErrText').value.trim();if(!t)return;state.errors.push({topic:document.getElementById('m4ErrTopic').value.trim(),text:t});document.getElementById('m4ErrText').value='';save()}}
function update(){const boxes=[...document.querySelectorAll('[data-read]')];boxes.forEach(b=>b.checked=!!state.read[b.dataset.read]);const n=boxes.filter(b=>b.checked).length,p=boxes.length?Math.round(n/boxes.length*100):0;document.getElementById('pct').textContent=p+'%';document.getElementById('bar').style.width=p+'%';document.querySelectorAll('[data-space]').forEach(b=>b.checked=!!state.space[b.dataset.space]);if(document.getElementById('m4Confidence'))document.getElementById('m4Confidence').value=state.review.confidence||'';if(document.getElementById('m4Weak'))document.getElementById('m4Weak').value=state.review.weak||'';if(document.getElementById('m4r1'))document.getElementById('m4r1').value=state.rounds.r1??'';if(document.getElementById('m4r2'))document.getElementById('m4r2').value=state.rounds.r2??'';if(document.getElementById('m4rf'))document.getElementById('m4rf').value=state.rounds.rf??'';const rr=document.getElementById('m4RoundPct');if(rr){const a=[];if(state.rounds.r1!==undefined)a.push('R1 '+Math.round(state.rounds.r1/20*100)+'%');if(state.rounds.r2!==undefined)a.push('R2 '+Math.round(state.rounds.r2/25*100)+'%');if(state.rounds.rf!==undefined)a.push('Final '+Math.round(state.rounds.rf/30*100)+'%');rr.textContent=a.join(' · ')}const el=document.getElementById('m4ErrList');if(el)el.innerHTML=state.errors.map((e,i)=>'<div class="card"><b>'+esc(e.topic||'Sem tópico')+'</b><p>'+esc(e.text)+'</p><button onclick="PtM4Runtime.delErr('+i+')">Excluir</button></div>').join('')}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active')});
window.PtM4Runtime={delErr:function(i){state.errors.splice(i,1);save()}};renderTheory();renderPanels();update();
})();